package net.civeira.phylax.feature.identity.user.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.crypto.PasswordHasher;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.user.domain.User;
import net.civeira.phylax.feature.identity.user.domain.valueobject.PasswordVO;

class PasswordValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of password of user")
  void test_password_value_holder_assign_plain_value() {
    Object holder = new Object();
    PasswordValueHolder<Object> value = new PasswordValueHolder<>(holder);
    PasswordHasher service = Mockito.mock(PasswordHasher.class);
    Mockito.when(service.hash("small")).thenReturn("$argon2id$example");
    Assertions.assertSame(holder, value.passwordPlain("small"), "Setters must return the holder");
    Assertions.assertTrue(value.getPasswordValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(Optional.of("$argon2id$example"), value.getPasswordStored(service),
        "The stored value must be resolved with the service");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of password of user")
  void test_password_value_holder_assign_value_object() {
    Object holder = new Object();
    PasswordValueHolder<Object> value = new PasswordValueHolder<>(holder);
    PasswordVO vo = PasswordVO.fromPlain("small");
    Assertions.assertFalse(value.getPasswordValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.password(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getPasswordValue().orElseThrow());
    Assertions.assertSame(holder, value.password(Optional.empty()));
    Assertions.assertFalse(value.getPasswordValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.password(Optional.of(vo)));
    Assertions.assertSame(vo, value.getPasswordValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of password of user against the original")
  void test_password_value_holder_read() {
    Object holder = new Object();
    PasswordValueHolder<Object> value = new PasswordValueHolder<>(holder);
    PasswordVO vo = PasswordVO.fromPlain("small");
    PasswordVO other = PasswordVO.fromPlain("small");
    User original = Mockito.mock(User.class);
    Mockito.when(original.getPasswordValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readPassword(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readPassword(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.password(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readPassword(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readPassword(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of password of user")
  void test_password_value_holder_unset() {
    Object holder = new Object();
    PasswordValueHolder<Object> value = new PasswordValueHolder<>(holder);
    PasswordVO vo = PasswordVO.fromPlain("small");
    value.password(vo);
    Assertions.assertSame(holder, value.unsetPasswordIfMatches("password_other"));
    Assertions.assertTrue(value.getPasswordValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetPasswordIfMatches("password"));
    Assertions.assertFalse(value.getPasswordValue().isPresent(),
        "The field name must clear the value");
    value.password(vo);
    Assertions.assertSame(holder, value.unsetPassword());
    Assertions.assertFalse(value.getPasswordValue().isPresent(), "Unset must clear the value");
  }
}
